<?php
require_once __DIR__.'/verificar_sesion.php';$id=(int)($_GET['id']??0);$db=conexion();
$s=$db->prepare('SELECT p.*,CONCAT(COALESCE(c.nombre,\'\'),\' \,\',COALESCE(c.apellidos,\'\')) cliente,c.correo FROM pedidos p INNER JOIN clientes c ON c.id=p.cliente_id WHERE p.id=?');$s->bind_param('i',$id);$s->execute();$pedido=$s->get_result()->fetch_assoc();$s->close();
if(!$pedido){$db->close();header('Location: pedidos.php');exit;}
$s=$db->prepare('SELECT d.id,d.cantidad,d.precio,pr.nombre,pr.imagen FROM detalle_pedido d LEFT JOIN productos pr ON pr.id=d.producto_id WHERE d.pedido_id=? ORDER BY d.id');$s->bind_param('i',$id);$s->execute();$items=$s->get_result();
$titulo='Detalle del pedido';require __DIR__.'/includes/encabezado.php';
?>
<main class="contenido"><a href="pedidos.php">← Volver a pedidos</a><h1>Pedido #<?php echo $id;?></h1><p><strong>Cliente:</strong> <?php echo e($pedido['cliente']);?> · <?php echo e($pedido['correo']);?></p><p><strong>Fecha:</strong> <?php echo e($pedido['fecha']);?> · <strong>Estado:</strong> <?php echo e($pedido['estado']);?></p><p><strong>Entrega:</strong> <?php echo e($pedido['telefono_entrega']);?> · <?php echo e($pedido['direccion_entrega'].', '.$pedido['barrio'].', '.$pedido['ciudad'].', '.$pedido['departamento'].' '.$pedido['codigo_postal']);?></p><p><strong>Pago:</strong> <?php echo e($pedido['metodo_pago']);?><?php if($pedido['referencia_entrega']):?> · <strong>Referencia:</strong> <?php echo e($pedido['referencia_entrega']);?><?php endif;?></p>
<div class="tabla-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th></tr></thead><tbody><?php $suma=0;while($it=$items->fetch_assoc()):$sub=(int)$it['cantidad']*(float)$it['precio'];$suma+=$sub;?><tr><td><?php echo e($it['nombre']??'Producto eliminado'); ?></td><td><?php echo (int)$it['cantidad'];?></td><td><?php echo e(precio_texto($it['precio']));?></td><td><?php echo e(precio_texto($sub));?></td></tr><?php endwhile;?></tbody><tfoot><tr><th colspan="3">Total pedido</th><th><?php echo e(precio_texto($pedido['total']));?></th></tr></tfoot></table></div></main>
<?php $s->close();$db->close();require __DIR__.'/includes/pie.php';?>
